returns text
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  v_yol text;
begin
  if auth.uid() is null then
    raise exception 'Kimlik dogrulamasi gerekli';
  end if;
  delete from public.hikayeler
   where id = p_hikaye_id and kullanici_id = auth.uid()
