  end if;
  update public.hikayeler set moderasyon_gizli = true where id = p_hikaye_id;
  perform moderasyon.kaydet('icerik_gizlendi', 'hikaye', p_hikaye_id,
    jsonb_build_object('sahip', v_sahip, 'gerekce', p_gerekce));
