  const ozetler = await profilOzetleriniGetir(satirlar.map((s) => s.kullanici_id))
  return satirlar
    .filter((s) => ozetler[s.kullanici_id])
    .sort((a, b) => b.goruldu.localeCompare(a.goruldu))
    .map((s) => ({
