old="""        onKapat={() => {
          setKaynakAcik(false)
          // Secim yapilmadan kapatildi ve elde fotograf yok: ekranin
          // anlami kalmadi, geri.
          if (!fotografUri) setTimeout(geri, 250)
        }}
        secimler={[
          { etiket: t('hikaye.kamera'), testID: 'hikaye-kamera', onSec: () => { setKaynakAcik(false); kameradanCek() } },
          { etiket: t('hikaye.galeri'), testID: 'hikaye-galeri', onSec: () => { setKaynakAcik(false); galeridenSec() } },
        ]}
"""
new="""        onKapat={() => {
          setKaynakAcik(false)
          // Secim yapilmadan kapatildi ve elde fotograf yok: ekranin
