import { supabase } from './supabase'
import {
  gelenIstekleriGetir,
  gidenIstekleriGetir,
  takipcilerimiGetir,
} from './bag-listeleri'
import { avatarlariGetir } from './akis'

jest.mock('./supabase', () => ({
  supabase: {
    from: jest.fn(),
    rpc: jest.fn(),
    auth: { getUser: jest.fn().mockResolvedValue({ data: { user: { id: 'ben' } } }), getSession: jest.fn().mockResolvedValue({ data: { session: { user: { id: 'ben' } } } }) },
  },
}))

// Avatarlar ayri yoldan (akis_profilleri) geliyor; burada mock, bu
// testler ad/kimlik cozumunu olcuyor. Avatar ikincil: okunamazsa null.
